import SkeletonService from '../../../../../src/services/SkeletonService';
import { getCollection } from '../../../../../src/lib/mongodb';
import { generateUniqueId } from '../../../../../src/utils/unique-generator';

/**
 * CustomCtrl - Laravel CustomCtrl.php equivalent
 * Handles custom operations for the automations module
 * Auto-generated by ModuleGenerator
 */
export default class CustomCtrl {
  /**
   * index method - Main handler
   * @param {Request} req 
   * @param {Response} res 
   * @returns {Promise<Response>}
   */
  async index(req, res) {
    try {
      console.log('🎯 CustomCtrl::index() called');

      const token = req.params?.token || req.body?.skeleton_token || req.query?.token;
      
      if (!token) {
        return res.status(400).json({
          status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }

      // Resolve token
      const reqSet = await SkeletonService.resolveToken(token);
      
      if (!reqSet || !reqSet.status || !reqSet.key) {
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid.'
        });
      }

      // Handle different configuration keys
      switch (reqSet.key) {
        case 'central_automations_custom': {
          const action = req.body?.action || req.query?.action;

          if (!action) {
            return res.status(400).json({
              status: false,
              title: 'Action Missing',
              message: 'No action was provided for automations custom controller.',
            });
          }

          // Route to specific domain enrichment actions
          if (action === 'domain_enrichment_upload') {
            return await this.handleDomainUpload(req, res);
          }

          if (action === 'domain_enrichment_start') {
            return await this.handleDomainStart(req, res);
          }

          if (action === 'domain_enrichment_export') {
            return await this.handleDomainExport(req, res);
          }

          if (action === 'domain_enrichment_reset_stuck') {
            return await this.handleDomainResetStuck(req, res);
          }

          return res.status(400).json({
            status: false,
            title: 'Invalid Action',
            message: `Unsupported action for automations: ${action}`,
          });
        }

        default:
          return res.status(400).json({
            status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.',
          });
      }

    } catch (error) {
      console.error('❌ CustomCtrl error:', error);
      return res.status(500).json({
        status: false,
        title: 'Error',
        message: error.message || 'An error occurred while processing the request.',
      });
    }
  }

  /**
   * Handle domain enrichment CSV upload (simplified: accepts list of domains)
   * Expects:
   *  - req.body.domains: string[] or comma-separated string
   * Returns:
   *  - batch_id
   *  - total_jobs
   */
  async handleDomainUpload(req, res) {
    const rawDomains = req.body?.domains;

    let domains = [];
    if (Array.isArray(rawDomains)) {
      domains = rawDomains;
    } else if (typeof rawDomains === 'string') {
      domains = rawDomains
        .split(/[\n,]+/)
        .map((d) => d.trim())
        .filter(Boolean);
    }

    if (!domains.length) {
      return res.status(400).json({
        status: false,
        title: 'No Domains',
        message: 'Please provide at least one domain.',
      });
    }

    const jobsCollection = await getCollection('domain_enrichment_jobs', 'automation');
    const batchId = generateUniqueId('DEB', 8); // Domain Enrichment Batch
    const now = new Date();
    const userId = req.user?.user_id || null;

    const docs = domains.map((domain) => ({
      batch_id: batchId,
      job_id: generateUniqueId('DEJ', 10),
      domain: String(domain).trim(),
      status: 'pending',
      attempts: 0,
      error: null,
      created_at: now,
      updated_at: now,
      created_by: userId,
      updated_by: userId,
    }));

    await jobsCollection.insertMany(docs);

    return res.status(200).json({
      status: true,
      title: 'Domains Uploaded',
      message: `Created ${docs.length} domain enrichment jobs.`,
      batch_id: batchId,
      total_jobs: docs.length,
    });
  }

  /**
   * Mark pending jobs for a batch as queued.
   * Queue enqueueing will be handled by a separate worker / queue producer.
   *
   * Expects:
   *  - req.body.batch_id or req.query.batch_id
   */
  async handleDomainStart(req, res) {
    const batchId = req.body?.batch_id || req.query?.batch_id;

    if (!batchId) {
      return res.status(400).json({
        status: false,
        title: 'Batch ID Missing',
        message: 'batch_id is required to start domain enrichment.',
      });
    }

    const jobsCollection = await getCollection('domain_enrichment_jobs', 'automation');

    const result = await jobsCollection.updateMany(
      {
        batch_id: batchId,
        status: { $in: ['pending', 'failed'] },
      },
      {
        $set: {
          status: 'queued',
          updated_at: new Date(),
        },
      },
    );

    // NOTE: actual enqueueing to Bull/Redis will be implemented in the worker step.

    return res.status(200).json({
      status: true,
      title: 'Batch Queued',
      message: `Marked ${result.modifiedCount} jobs as queued for batch ${batchId}.`,
      batch_id: batchId,
      queued_jobs: result.modifiedCount,
    });
  }

  /**
   * Export completed results for a batch as CSV (domain,company_name,address,phone,address_type).
   * Supports multi-branch addresses - creates one row per address.
   *
   * Expects:
   *  - req.query.batch_id (optional; if omitted, export all completed)
   */
  async handleDomainExport(req, res) {
    const batchId = req.query?.batch_id || req.body?.batch_id || null;
    const resultsCollection = await getCollection('domain_enrichment_results', 'automation');

    const query = { status: { $in: ['completed', 'failed'] } };
    if (batchId) {
      query.batch_id = batchId;
    }

    const cursor = resultsCollection
      .find(query)
      .project({
        _id: 0,
        domain: 1,
        company_name: 1,
        address: 1,
        all_addresses: 1,
        phone: 1,
      });

    const rows = await cursor.toArray();

    // CSV with address_type column to distinguish HQ from branches
    let csv = 'domain,company_name,address,phone,address_type\n';

    for (const row of rows) {
      const safe = (v) =>
        String(v ?? '')
          .replace(/"/g, '""')
          .trim();

      // Get all addresses (use all_addresses if available, otherwise just address)
      const addresses = row.all_addresses && row.all_addresses.length > 0
        ? row.all_addresses
        : [row.address].filter(Boolean);

      if (addresses.length === 0) {
        // No addresses - still output domain info
        const line = [
          `"${safe(row.domain)}"`,
          `"${safe(row.company_name)}"`,
          `""`,
          `"${safe(row.phone)}"`,
          `""`,
        ].join(',');
        csv += `${line}\n`;
      } else {
        // Output one row per address
        addresses.forEach((addr, idx) => {
          const addressType = idx === 0 ? 'HQ' : 'Branch';
          const line = [
            `"${safe(row.domain)}"`,
            `"${safe(row.company_name)}"`,
            `"${safe(addr)}"`,
            `"${safe(row.phone)}"`,
            `"${addressType}"`,
          ].join(',');
          csv += `${line}\n`;
        });
      }
    }

    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader(
      'Content-Disposition',
      `attachment; filename="domain_enrichment_${batchId || 'all'}.csv"`,
    );

    return res.status(200).send(csv);
  }


  /**
   * Reset stuck 'processing' jobs back to 'queued'
   * Useful when worker crashes or jobs get stuck
   *
   * Expects:
   *  - req.query.batch_id (optional; if omitted, reset all stuck jobs)
   *  - req.query.timeout_minutes (optional; default 5 minutes)
   */
  async handleDomainResetStuck(req, res) {
    const batchId = req.query?.batch_id || req.body?.batch_id || null;
    const timeoutMinutes = parseInt(req.query?.timeout_minutes || req.body?.timeout_minutes || '5', 10);
    const timeoutMs = timeoutMinutes * 60 * 1000;
    const timeoutThreshold = new Date(Date.now() - timeoutMs);

    const jobsCollection = await getCollection('domain_enrichment_jobs', 'automation');

    const query = {
      status: 'processing',
      updated_at: { $lt: timeoutThreshold },
    };

    if (batchId) {
      query.batch_id = batchId;
    }

    const result = await jobsCollection.updateMany(query, {
      $set: {
        status: 'queued',
        updated_at: new Date(),
      },
    });

    return res.status(200).json({
      status: true,
      title: 'Stuck Jobs Reset',
      message: `Reset ${result.modifiedCount} stuck 'processing' jobs back to 'queued'${batchId ? ` for batch ${batchId}` : ''}.`,
      reset_count: result.modifiedCount,
      batch_id: batchId || null,
      timeout_minutes: timeoutMinutes,
    });
  }
}
